    Specification(standard_code='13', spec_code='h', standard_title='Knowledge, Theory, Skills, and Values', spec_text='Dealing effectively with conflict on varying levels of human service delivery systems 4. Disciplined Inquiry and Information Literacy Context: The delivery of effective human services depends on the appropriate integration of various forms of information.', program_level='masters', version="2025"),
    Specification(standard_code='14', spec_code='a', standard_title='Knowledge, Theory, Skills, and Values', spec_text='Knowledge and skills to obtain information through observation and research.', program_level='masters', version="2025"),
